import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.CchDE9cb.js";const p=JSON.parse('{"title":"Mutation-test review — 2026-07-18","description":"A follow-up mutation-testing pass after fixing test-scope drift, scoring 92.37% with no runner errors.","frontmatter":{"title":"Mutation-test review — 2026-07-18","description":"A follow-up mutation-testing pass after fixing test-scope drift, scoring 92.37% with no runner errors."},"headers":[],"relativePath":"security/mutation-review-2026-07-18.md","filePath":"security/mutation-review-2026-07-18.md","lastUpdated":1785253498000}'),o={name:"security/mutation-review-2026-07-18.md"};function n(s,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="mutation-test-review-—-2026-07-18" tabindex="-1">Mutation-test review — 2026-07-18 <a class="header-anchor" href="#mutation-test-review-—-2026-07-18" aria-label="Permalink to &quot;Mutation-test review — 2026-07-18&quot;">​</a></h1><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The corrected pure-logic mutation profile clears its 85% release threshold at <strong>92.37%</strong>, with no runner errors. The shared domain and library core scores <strong>95.20%</strong>; tenant predicates, private-name projection, scheduling-day rules and password-reset failure mapping remain at 100%.</p><p>The first run exposed scope drift rather than a product defect. Two React hooks added under the scheduler directory were caught by the existing broad TypeScript glob even though the documented profile intentionally targets pure helpers. Those hooks contributed 507 lifecycle/event mutants, including 216 survivors, 81 uncovered mutants and two Vitest-runner serialization errors. They are now explicitly excluded by the scheduler hook naming convention. Their behavior remains covered by component tests and the Chromium, Firefox and WebKit E2E matrix.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><code>stryker.config.json</code> mutates the pure shared domain/library core, pure scheduler helpers, browser helpers and reset-page failure mapper. It excludes React hooks and component rendering, along with the entire <code>server/</code> implementation. The score therefore supports shared validation and pure browser-logic claims; it is not evidence for Fastify, Better Auth, session, MFA, CSRF or SQLite route authorization. Those controls rely on the server gate, focused integration tests, E2E and manual security review.</p><p>The generated interactive report is <code>reports/mutation/mutation.html</code>. It remains a local ignored artifact; this document preserves the reviewed outcome.</p><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">2026-07-15 reviewed run</th><th style="text-align:right;">2026-07-18 reviewed run</th></tr></thead><tbody><tr><td>Mutants</td><td style="text-align:right;">2,988</td><td style="text-align:right;">3,068</td></tr><tr><td>Killed by assertions</td><td style="text-align:right;">2,763</td><td style="text-align:right;">2,823</td></tr><tr><td>Timed out</td><td style="text-align:right;">11</td><td style="text-align:right;">11</td></tr><tr><td>Survived</td><td style="text-align:right;">177</td><td style="text-align:right;">190</td></tr><tr><td>No coverage</td><td style="text-align:right;">37</td><td style="text-align:right;">44</td></tr><tr><td>Errors</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td></tr><tr><td>Total mutation score</td><td style="text-align:right;">92.84%</td><td style="text-align:right;"><strong>92.37%</strong></td></tr><tr><td>Covered-code score</td><td style="text-align:right;">94.00%</td><td style="text-align:right;"><strong>93.72%</strong></td></tr></tbody></table><p>The result exceeds the configured break threshold by 7.37 percentage points. All 1,720 tests in the mutation runner&#39;s initial per-test coverage pass succeeded before the 3,068 mutants ran.</p><h2 id="survivor-triage" tabindex="-1">Survivor triage <a class="header-anchor" href="#survivor-triage" aria-label="Permalink to &quot;Survivor triage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Review outcome</th></tr></thead><tbody><tr><td>Tenant and private-data predicates</td><td><code>tenancy.ts</code> and <code>privateNames.ts</code> remain at 100%. No tenant-isolation or confidential-name mutant survives.</td></tr><tr><td>Access boundary</td><td>One guard mutant survives where an unknown canonical action already resolves to no minimum role; the original and mutant both fail closed. Exhaustive role/action and untyped-boundary tests remain in place.</td></tr><tr><td>Lifecycle and destructive actions</td><td>Surviving impact-preview selectors and timestamp guards either converge on the same conservative result or exercise invalid values already rejected by the write boundary. No archive, delete, restore or purge permission bypass was found.</td></tr><tr><td>Allocation/reference validation</td><td><code>mutations.ts</code> remains at 96.03%. Surviving type/id-remap guards cover malformed import shapes that converge on the same sanitised result; missing, cross-account, inactive and reassigned references remain explicitly rejected.</td></tr><tr><td>Import and referential repair</td><td>Integrity and import survivors are defensive type guards, equivalent ISO-date checks or repair branches whose adversarial inputs converge on the asserted canonical output. No fail-open scoped reference was found.</td></tr><tr><td>Reset failure mapping</td><td><code>resetPasswordFailure.ts</code> remains at 100%.</td></tr><tr><td>Pure scheduler helpers</td><td>The scheduler helper group scores 92.87% with no uncovered mutants. Drag math and week snapping remain at 100%; geometry/virtualisation timeouts are counted as detected.</td></tr><tr><td>Timezone and tour presentation</td><td>Low-scoring timezone label parsing and the dynamically imported product tour remain visible product-test debt. They carry no authorization, tenant-isolation or confidentiality claim.</td></tr><tr><td>Timed-out mutants</td><td>All 11 are in date, colour, fuzzy-search, geometry or virtualisation helpers. Stryker counts them as detected, but they remain weaker evidence than assertion kills.</td></tr></tbody></table><h2 id="acceptance-and-follow-up" tabindex="-1">Acceptance and follow-up <a class="header-anchor" href="#acceptance-and-follow-up" aria-label="Permalink to &quot;Acceptance and follow-up&quot;">​</a></h2><ul><li>The corrected profile has no compile/runtime errors and remains above both the 90% high-water mark and the 85% break threshold.</li><li>React hooks must keep behavior-focused component and cross-browser coverage; pure calculations extracted from a hook belong back in the mutation profile.</li><li>Any future survivor in tenancy, access, private-name projection, import/reference validation, reset failure mapping or destructive-action support code requires manual triage regardless of the aggregate score.</li><li>Timezone labeling and the product tour remain the clearest non-security mutation-testing debt.</li></ul>',14)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
